def partial_pool(groups, tau2, sigma2):
    if not groups:
        raise ValueError("no groups to pool")
    if tau2 < 0 or sigma2 < 0:
        raise ValueError("variances must be non-negative")
    if tau2 == 0 and sigma2 == 0:
        raise ValueError("both variances are zero, so no weight is defined")
    observations = []
    for name, values in groups.items():
        if not values:
            raise ValueError(f"group {name!r} has no observations")
        observations.extend(values)
    grand = sum(observations) / len(observations)
    weights = {}
    estimates = {}
    for name, values in groups.items():
        n = len(values)
        mean = sum(values) / n
        w = 1.0 if sigma2 == 0 else tau2 / (tau2 + sigma2 / n)
        weights[name] = w
        estimates[name] = w * mean + (1 - w) * grand
    return {"grand": grand, "icc": tau2 / (tau2 + sigma2),
            "weights": weights, "estimates": estimates}
